#!/usr/bin/env bash
set -euo pipefail
cd "$(git rev-parse --show-toplevel)"

[[ -n "$(docker compose ps --status running -q postgres)" ]] || {
    echo "ERROR: PostgreSQL container is not running." >&2
    exit 1
}

# This name is generated by this script, never derived from the owner database.
test_database="alycia_s7_test_$(date +%s)_${RANDOM}"
[[ "$test_database" =~ ^alycia_s7_test_[a-z0-9_]+$ ]] || exit 1

docker compose exec -T postgres sh -c \
    'exec createdb -U "$POSTGRES_USER" "$1"' _ "$test_database"
echo "Created isolated test database: $test_database"

migration_sql=$(mktemp)
trap 'rm -f "$migration_sql"' EXIT

# Recreate a real S6 schema, then seed Workspaces before S7 migrations.
dotnet tool run dotnet-ef migrations script \
    0 20261105211324_InitialWorkspaces \
    --project src/Alycia.Modules.Workspaces.Infrastructure \
    --startup-project src/Alycia.Modules.Workspaces.Infrastructure \
    --context WorkspacesDbContext \
    --output "$migration_sql"

docker compose exec -T postgres sh -c \
    'exec psql -X -v ON_ERROR_STOP=1 -U "$POSTGRES_USER" -d "$1"' \
    _ "$test_database" < "$migration_sql"

docker compose exec -T postgres sh -c \
    'exec psql -X -v ON_ERROR_STOP=1 -U "$POSTGRES_USER" -d "$1"' \
    _ "$test_database" <<'SQL'
INSERT INTO workspaces.workspaces (id, name, created_at_utc) VALUES
    ('00000000-0000-0000-0000-000000000101', 'S6 Existing One', NOW()),
    ('00000000-0000-0000-0000-000000000102', 'S6 Existing Two', NOW());
SQL

# Both module migrations are explicit, ordered and repeatable.
ALYCIA_MIGRATE_DATABASE="$test_database" make migrate
ALYCIA_MIGRATE_DATABASE="$test_database" make migrate

ALYCIA_S7_TEST_DATABASE="$test_database" docker compose --profile test run \
    --rm --no-deps --user "$(id -u):$(id -g)" \
    -e HOME=/tmp -e DOTNET_CLI_HOME=/tmp \
    -e NUGET_PACKAGES=/tmp/alycia-nuget \
    s7-integration

# Only the randomly named test database is deleted on success.
docker compose exec -T postgres sh -c \
    'exec dropdb -U "$POSTGRES_USER" "$1"' _ "$test_database"
echo "S7 isolated PostgreSQL integration passed; test database removed."
